package com.nexushr.controller; import com.nexushr.dto.RequestDtos.*; import com.nexushr.entity.LeaveRequest; import com.nexushr.service.LeaveService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.security.Principal; import java.util.*; @RestController @RequestMapping("/leaves") public class LeaveController {final LeaveService s;public LeaveController(LeaveService s){this.s=s;} @GetMapping("/me") public List<LeaveRequest> mine(Principal p){return s.mine(p.getName());} @PostMapping public LeaveRequest create(Principal p,@RequestBody LeaveRequestDto x){return s.create(p.getName(),x);} @GetMapping("/pending") @PreAuthorize("hasAnyRole('ADMIN','HR')") public List<LeaveRequest> pending(){return s.pending();} @PatchMapping("/{id}") @PreAuthorize("hasAnyRole('ADMIN','HR')") public LeaveRequest decide(@PathVariable UUID id,@RequestBody LeaveDecision x){return s.decide(id,x);}}
